frappe.listview_settings['Journal Entry'] = {
    onload: function(listview) {
        listview.page.add_inner_button(__('Apportion Amenity Costs'), function() {
            
            // 1. Create a quick prompt dialog for the company selection
            let d = new frappe.ui.Dialog({
                title: __('Select Company for Apportionment'),
                fields: [
                    {
                        fieldname: 'company',
                        label: __('Company'),
                        fieldtype: 'Link',
                        options: 'Company',
                        reqd: 1,
                        // Automatically default to the user's current active company
                        default: frappe.defaults.get_user_default('company') || frappe.boot.default_company
                    }
                ],
                primary_action_label: __('Generate Apportionment JE'),
                primary_action(values) {
                    d.hide();
                    
                    // 2. Call the backend API and pass the selected company
                    frappe.call({
                        method: "apportion_amenity_costs",
                        args: {
                            company_name: values.company
                        },
                        freeze: true,
                        freeze_message: __("Calculating and generating Journal Entry..."),
                        callback: function(r) {
                            if (!r.exc) {
                                listview.refresh();
                            }
                        }
                    });
                }
            });
            
            d.show();
        });
    }
};

frappe.ui.form.on('Resident Pets', {
    // Triggers when the admin selects the flat
    flat: function(frm) {
        if (frm.doc.flat) {

            // 1. Check for active tenant
            frappe.db.get_value('Tenants', 
                {'parent': frm.doc.flat, 'active': 1}, 
                'name', 
                (r) => {
                    if (r && r.name) {
                        frm.set_value('belongs_to', 'Tenant');
                        frm.set_value('tenant_reference', r.name);
                    } else {
                        // 2. Check for active owner
                        frappe.db.get_value('Custom Owners', 
                            {'parent': frm.doc.flat, 'active': 1}, 
                            'name', 
                            (r2) => {
                                if (r2 && r2.name) {
                                    frm.set_value('belongs_to', 'Owner');
                                    frm.set_value('owner_reference', r2.name);
                                } else {
                                    frappe.msgprint(`No active resident found for Flat ${frm.doc.flat}`);
                                }
                            }
                        );
                    }
                }
            );
        } else {
            // Clear fields if flat is removed
            frm.set_value('belongs_to', '');
            frm.set_value('tenant_reference', '');
            frm.set_value('owner_reference', '');
        }
    }
});

frappe.ui.form.on('Resident Vehicles', {
    // This function triggers the moment someone changes the "flat" field
    flat: function(frm) {
        if (frm.doc.flat) {

            // 1. First, check if the flat has an active tenant
            frappe.db.get_value('Tenants', 
                {'parent': frm.doc.flat, 'active': 1}, 
                'name', 
                (r) => {

                    if (r && r.name) {
                        // Active tenant found! Set the dropdown and link the tenant.
                        frm.set_value('belongs_to', 'Tenant');
                        frm.set_value('tenant_reference', r.name);

                    } else {
                        // 2. No active tenant found. Let's check for an active owner instead.
                        frappe.db.get_value('Custom Owners', 
                            {'parent': frm.doc.flat, 'active': 1}, 
                            'name', 
                            (r2) => {
                                if (r2 && r2.name) {
                                    // Active owner found! Set the dropdown and link the owner.
                                    frm.set_value('belongs_to', 'Owner');
                                    frm.set_value('owner_reference', r2.name);
                                } else {
                                    frappe.msgprint(`No active resident found for Flat ${frm.doc.flat}`);
                                }
                            }
                        );
                    }
                }
            );
        } else {
            // If the admin clears the flat field, clear out our auto-populated fields too
            frm.set_value('belongs_to', '');
            frm.set_value('tenant_reference', '');
            frm.set_value('owner_reference', '');
        }
    }
});

frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        if (frm.doc.__islocal) return;

        // 1. Fetch and Display Active Owner
        frm.get_field('custom_owner_details').$wrapper.html('<i>Loading Owner...</i>');
        frappe.db.get_list('Owners', {
            filters: { 'flat': frm.doc.name, 'active': 1 },
            fields: ['owner_name', 'mobile_no', 'email']
        }).then(records => {
            if(records && records.length > 0) {
                let owner = records[0];
                let html = `
                    <div style="padding: 10px; background-color: #f4f5f6; border-radius: 6px; border-left: 4px solid #2f73e5;">
                        <b style="color: #36414c; font-size: 14px;">${owner.owner_name}</b><br>
                        <span style="color: #6c7680;">📞 ${owner.mobile_no || 'N/A'} &nbsp; | &nbsp; ✉️ ${owner.email || 'N/A'}</span>
                    </div>`;
                frm.get_field('custom_owner_details').$wrapper.html(html);
            } else {
                frm.get_field('custom_owner_details').$wrapper.html('<b style="color: #e74c3c;">No Active Owner Found</b>');
            }
        });

        // 2. Fetch and Display Active Tenant
        if (frm.doc.custom_let_out_for_rent) {
            frm.get_field('custom_tenant_details').$wrapper.html('<i>Loading Tenant...</i>');
            frappe.db.get_list('Tenants', {
                filters: { 'flat': frm.doc.name, 'active': 1 },
                fields: ['tenant_name', 'mobile_no', 'email']
            }).then(records => {
                if(records && records.length > 0) {
                    let tenant = records[0];
                    let html = `
                        <div style="padding: 10px; background-color: #f4f5f6; border-radius: 6px; border-left: 4px solid #e67e22;">
                            <b style="color: #36414c; font-size: 14px;">${tenant.tenant_name}</b><br>
                            <span style="color: #6c7680;">📞 ${tenant.mobile_no || 'N/A'} &nbsp; | &nbsp; ✉️ ${tenant.email || 'N/A'}</span>
                        </div>`;
                    frm.get_field('custom_tenant_details').$wrapper.html(html);
                } else {
                    frm.get_field('custom_tenant_details').$wrapper.html('<b style="color: #e74c3c;">No Active Tenant Found</b>');
                }
            });
        } else {
            frm.get_field('custom_tenant_details').$wrapper.html('<i style="color: #6c7680;">Flat is not let out for rent.</i>');
        }
    }
});

frappe.ui.form.on('Owners', {
    validate: function(frm) {
        // Only run this check if the user is trying to save an ACTIVE owner
        if (frm.doc.active) {
            
            // If the user already clicked "Yes" on the prompt, let the save continue
            if (frm.doc.__deactivate_confirmed) return;

            // Pause the save process to do an asynchronous database check
            frappe.validated = false;
            
            frappe.db.get_list('Owners', {
                filters: {
                    'flat': frm.doc.flat,
                    'active': 1,
                    'name': ['!=', frm.doc.name] // Exclude the current document
                },
                fields: ['name']
            }).then(records => {
                if (records && records.length > 0) {
                    let old_owner = records[0].name;
                    
                    // Show the interactive prompt
                    frappe.confirm(
                        `An active owner (<b>${old_owner}</b>) already exists for Flat ${frm.doc.flat}. <br><br>Do you want to deactivate them and make this new owner active?`,
                        () => {
                            // User clicked YES: Set the bypass flag and trigger save again
                            frm.doc.__deactivate_confirmed = true;
                            frm.save();
                        },
                        () => {
                            // User clicked NO: Cancel the save
                            frappe.msgprint("Save cancelled. You can uncheck 'Active' if you want to save this owner as inactive.");
                        }
                    );
                } else {
                    // No existing active owner found, proceed with save normally
                    frm.doc.__deactivate_confirmed = true;
                    frm.save();
                }
            });
        }
    }
});
